def transform(grid):
    h = len(grid)
    w = len(grid[0])
    divider = next(c for c in range(w) if all(row[c] == 4 for row in grid))
    out_w = w - divider - 1
    out = [[0] * out_w for _ in range(h)]

    # The 5 marks the starting point of the path in the output panel.
    marker_r, marker_c = next(
        (r, c) for r, row in enumerate(grid)
        for c in range(divider + 1, w) if row[c] == 5
    )
    x = marker_c - divider - 1
    out[marker_r][x] = 5
    y = marker_r

    # Tiles are read down the left column first, then down the right column.
    tiles = []
    for tile_col in (0, 4):
        for top in range(0, h - 2, 4):
            cells = [
                grid[r][c]
                for r in range(top, top + 3)
                for c in range(tile_col, tile_col + 3)
                if grid[r][c] not in (0, 4, 5)
            ]
            if cells:
                tiles.append(cells[0])

    # Each tile directs the path and sets the length of its colored segment.
    rules = {
        1: ("R", 3),
        2: ("L", 2),
        3: ("L", 4),
        6: ("D", 2),
    }

    for color in tiles:
        direction, length = rules[color]
        y += 1
        if direction == "R":
            for dx in range(length):
                if 0 <= y < h and 0 <= x + dx < out_w:
                    out[y][x + dx] = color
            x += length - 1
        elif direction == "L":
            for dx in range(length):
                if 0 <= y < h and 0 <= x - dx < out_w:
                    out[y][x - dx] = color
            x -= length - 1
        else:
            for dy in range(length):
                if 0 <= y + dy < h and 0 <= x < out_w:
                    out[y + dy][x] = color
            y += length - 1

    return out
